#pragma once

#include "core/diffchunk.h"
#include "core/diffutil.h"
#include "core/myers.h"

#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonValue>
#include <QStringList>
#include <QTest>

namespace testutils {

//! Reference results generated by tools/generate_reference_data.py from
//! the original Python implementation.
inline const QJsonObject &reference()
{
    static const QJsonObject data = [] {
        QFile file(QStringLiteral(MELD_TEST_DATA_DIR "/reference.json"));
        if (!file.open(QIODevice::ReadOnly))
            qFatal("Couldn't open reference data %s", qPrintable(file.fileName()));
        return QJsonDocument::fromJson(file.readAll()).object();
    }();
    return data;
}

inline QStringList toStringList(const QJsonValue &value)
{
    QStringList result;
    for (const QJsonValue &v : value.toArray())
        result.append(v.toString());
    return result;
}

inline QJsonValue toJson(const meld::OptChunk &chunk)
{
    if (!chunk)
        return QJsonValue::Null;
    return QJsonArray{meld::chunkTagName(chunk->tag), chunk->start_a, chunk->end_a, chunk->start_b,
                      chunk->end_b};
}

inline QJsonValue toJson(const meld::DiffChunk &chunk)
{
    return toJson(meld::OptChunk(chunk));
}

inline QJsonValue toJson(const meld::MergedChunk &chunk)
{
    return QJsonArray{toJson(chunk.first), toJson(chunk.second)};
}

template<typename Container>
QJsonArray toJsonArray(const Container &items)
{
    QJsonArray array;
    for (const auto &item : items)
        array.append(toJson(item));
    return array;
}

inline QJsonArray blocksToJson(const std::vector<meld::MatchingBlock> &blocks)
{
    QJsonArray array;
    for (const meld::MatchingBlock &b : blocks)
        array.append(QJsonArray{b.a, b.b, b.size});
    return array;
}

inline QJsonValue optIntJson(const std::optional<int> &value)
{
    return value ? QJsonValue(*value) : QJsonValue(QJsonValue::Null);
}

inline QString compact(const QJsonValue &value)
{
    if (value.isArray())
        return QString::fromUtf8(QJsonDocument(value.toArray()).toJson(QJsonDocument::Compact));
    if (value.isObject())
        return QString::fromUtf8(QJsonDocument(value.toObject()).toJson(QJsonDocument::Compact));
    return QString::fromUtf8(QJsonDocument(QJsonArray{value}).toJson(QJsonDocument::Compact));
}

//! Sort an array of JSON values by their compact serialisation, mirroring
//! the sorting done by the reference generator for sets.
inline QJsonArray sortedByJson(QJsonArray array)
{
    std::vector<QJsonValue> values(array.begin(), array.end());
    std::sort(values.begin(), values.end(), [](const QJsonValue &a, const QJsonValue &b) {
        return compact(a) < compact(b);
    });
    QJsonArray result;
    for (const QJsonValue &v : values)
        result.append(v);
    return result;
}

} // namespace testutils

#define COMPARE_JSON(actual, expected, context)                                                    \
    do {                                                                                           \
        const QJsonValue actual_ = (actual);                                                       \
        const QJsonValue expected_ = (expected);                                                   \
        if (actual_ != expected_) {                                                                \
            QFAIL(qPrintable(QStringLiteral("%1\n   actual: %2\n expected: %3")                    \
                                 .arg(context, testutils::compact(actual_),                        \
                                      testutils::compact(expected_))));                            \
        }                                                                                          \
    } while (false)
